pub(super) const BILLING: &str = "diff --git a/services/billing/src/client.rs b/services/billing/src/client.rs\nindex 4e1a7c2..9b03d5f 100644\n--- a/services/billing/src/client.rs\n+++ b/services/billing/src/client.rs\n@@ -1,6 +1,5 @@\n use std::time::Duration;\n \n-use legacy_auth::{Session, Token};\n-use legacy_auth::session::refresh;\n+use auth::{Client as AuthClient, Token};\n \n use crate::error::Error;\n@@ -24,6 +23,5 @@\n pub struct BillingClient {\n     http: reqwest::Client,\n-    session: Session,\n-    refresh_every: Duration,\n+    auth: AuthClient,\n     base: Url,\n }\n@@ -41,15 +39,12 @@\n impl BillingClient {\n     pub async fn charge(&self, req: &Charge) -> Result<Receipt, Error> {\n-        if self.session.expired() {\n-            refresh(&self.session).await?;\n-        }\n-        let token = self.session.token();\n+        let token: Token = self.auth.token().await?;\n         let resp = self\n             .http\n             .post(self.base.join(\"charges\")?)\n             .bearer_auth(token.as_str())\n             .json(req)\n             .send()\n             .await?;\n         resp.error_for_status()?.json().await.map_err(Error::from)\n     }\n@@ -88,10 +83,10 @@\n     pub async fn refund(&self, id: &ChargeId) -> Result<(), Error> {\n-        let token = self.session.token();\n+        let token = self.auth.token().await?;\n         self.http\n             .post(self.base.join(&format!(\"charges/{id}/refund\"))?)\n             .bearer_auth(token.as_str())\n             .send()\n             .await?\n             .error_for_status()?;\n         Ok(())\n     }\ndiff --git a/services/billing/Cargo.toml b/services/billing/Cargo.toml\nindex 4e1a7c2..9b03d5f 100644\n--- a/services/billing/Cargo.toml\n+++ b/services/billing/Cargo.toml\n@@ -9,5 +9,5 @@\n [dependencies]\n anyhow = \"1\"\n-legacy-auth = { path = \"../../legacy/auth\" }\n+auth = { path = \"../../crates/auth\", version = \"0.4\" }\n reqwest = { version = \"0.12\", features = [\"json\"] }\n serde = { version = \"1\", features = [\"derive\"] }\ndiff --git a/services/billing/src/session.rs b/services/billing/src/session.rs\ndeleted file mode 100644\nindex 7c1d0e2..0000000\n--- a/services/billing/src/session.rs\n+++ /dev/null\n@@ -1,6 +0,0 @@\n-//! Session refresh for the old auth module.\n-use legacy_auth::Session;\n-\n-pub(crate) fn needs_refresh(s: &Session) -> bool {\n-    s.expires_in().as_secs() < 30\n-}\ndiff --git a/services/billing/tests/auth.rs b/services/billing/tests/auth.rs\nnew file mode 100644\nindex 0000000..3a9f1b4\n--- /dev/null\n+++ b/services/billing/tests/auth.rs\n@@ -0,0 +1,9 @@\n+use billing::BillingClient;\n+\n+#[tokio::test]\n+async fn charges_with_a_token_from_the_new_auth_client() {\n+    let auth = auth::testing::client();\n+    let billing = BillingClient::new(auth, \"http://localhost:9\".parse().unwrap());\n+    let receipt = billing.charge(&billing::testing::charge(100)).await.unwrap();\n+    assert_eq!(receipt.amount, 100);\n+}\n";

